def admit(active, waiting, budget, slots):
    # Check if any waiting reservation exceeds the total budget
    for value in waiting:
        if value > budget:
            raise ValueError

    admitted = []
    active_sum = sum(active)
    slots_used = len(active)

    for value in waiting:
        # Check if this reservation can fit within both budget and slots
        if active_sum + sum(admitted) + value <= budget and slots_used + len(admitted) < slots:
            admitted.append(value)
        else:
            # Stop at the first reservation that doesn't fit
            break

    # Return remaining items (those not admitted)
    waiting_list = list(waiting)  # Create a copy to avoid modifying original
    for item in admitted:
        if item in waiting_list:
            waiting_list.remove(item)

    return admitted, waiting_list

